WITH faturamento_mes AS ( SELECT mes, SUM(faturamento) AS faturamento_mes FROM itens WHERE mes BETWEEN '2026-01' AND '2026-12' GROUP BY mes ), primeira AS ( SELECT AVG(faturamento_mes) AS media1 FROM faturamento_mes WHERE substr(mes, 6, 2) BETWEEN '01' AND '06' ), segunda AS ( SELECT AVG(faturamento_mes) AS media2 FROM faturamento_mes WHERE substr(mes, 6, 2) BETWEEN '07' AND '12' ) SELECT ROUND(primeira.media1, 2) AS media_primeira_metade, ROUND(segunda.media2, 2) AS media_segunda_metade, ROUND(((segunda.media2 - primeira.media1) / NULLIF(primeira.media1, 0)) * 100, 1) AS variacao_percentual FROM primeira, segunda;